using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------- configuration ----------
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

// ---------- tools ----------
var notebook = new Notebook();

var tools = new AIFunction[]
{
    AIFunctionFactory.Create(
        ([Description("The search query")] string query) =>
        {
            Console.WriteLine($"  🌐 Searching: \"{query}\"");
            return WebSearch.SearchAsync(query);
        },
        "web_search",
        "Search the web for information. Returns a list of result snippets."),

    AIFunctionFactory.Create(
        ([Description("Title for the note")] string title,
         [Description("Content of the note")] string content) =>
        {
            notebook.Add(title, content);
            Console.WriteLine($"  📝 Note saved: \"{title}\"");
            return $"Note \"{title}\" saved successfully.";
        },
        "save_note",
        "Save a research note for later use in the summary."),

    AIFunctionFactory.Create(
        () =>
        {
            Console.WriteLine("  📖 Reading all notes…");
            return notebook.ReadAll();
        },
        "read_notes",
        "Retrieve all previously saved research notes."),
};

// ---------- chat client with automatic tool handling ----------
IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()   // auto-invokes tools when the model requests them
    .Build();

var chatOptions = new ChatOptions { Tools = [.. tools] };

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research assistant. Your job is to research the given topic
        thoroughly using the web_search tool, save important findings with the
        save_note tool, then produce a well-structured markdown summary.

        Workflow:
        1. Search the web 2-4 times with varied queries to gather broad information.
        2. Save the most important findings as notes (at least 3 notes).
        3. Read your notes back with read_notes.
        4. Write a final summary in markdown with sections, key facts, and sources.

        Always search before summarising. Never fabricate information.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary:\n\n{topic}"),
};

// ---------- agent loop ----------
Console.WriteLine("─── Agent Working ───");

var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n─── Research Summary ───\n");
Console.WriteLine(response.Text);

if (notebook.Count > 0)
{
    Console.WriteLine($"\n📓 {notebook.Count} note(s) were saved during research.");
}

// ---------- helpers ----------
static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input)
        ? "Recent advances in renewable energy technology in 2026"
        : input;
}

// ---------- Notebook (note-taking tool) ----------
sealed class Notebook
{
    private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];

    public int Count => _notes.Count;

    public void Add(string title, string content) =>
        _notes.Add((title, content, DateTime.UtcNow));

    public string ReadAll() =>
        _notes.Count == 0
            ? "No notes saved yet."
            : string.Join("\n\n", _notes.Select((n, i) =>
                $"--- Note {i + 1}: {n.Title} ({n.Timestamp:u}) ---\n{n.Content}"));
}

// ---------- Web search (uses Bing or falls back to a stub) ----------
static class WebSearch
{
    private static readonly HttpClient Http = new();

    public static async Task<string> SearchAsync(string query)
    {
        // Try Bing Search API if a key is available
        var bingKey = Environment.GetEnvironmentVariable("BING_SEARCH_API_KEY");
        if (!string.IsNullOrEmpty(bingKey))
        {
            return await BingSearchAsync(query, bingKey);
        }

        // Fallback: fetch a summary from Wikipedia's API
        return await WikipediaFallbackAsync(query);
    }

    private static async Task<string> BingSearchAsync(string query, string apiKey)
    {
        var url = $"https://api.bing.microsoft.com/v7.0/search?q={Uri.EscapeDataString(query)}&count=5";
        using var request = new HttpRequestMessage(HttpMethod.Get, url);
        request.Headers.Add("Ocp-Apim-Subscription-Key", apiKey);

        var response = await Http.SendAsync(request);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync();
        // Parse snippets from JSON
        var results = System.Text.Json.JsonDocument.Parse(json);
        var snippets = new List<string>();

        if (results.RootElement.TryGetProperty("webPages", out var webPages)
            && webPages.TryGetProperty("value", out var values))
        {
            foreach (var item in values.EnumerateArray().Take(5))
            {
                var name = item.GetProperty("name").GetString();
                var snippet = item.GetProperty("snippet").GetString();
                var itemUrl = item.GetProperty("url").GetString();
                snippets.Add($"• {name}\n  {snippet}\n  Source: {itemUrl}");
            }
        }

        return snippets.Count > 0
            ? string.Join("\n\n", snippets)
            : "No results found.";
    }

    private static async Task<string> WikipediaFallbackAsync(string query)
    {
        var url = $"https://en.wikipedia.org/api/rest_v1/page/summary/{Uri.EscapeDataString(query)}";
        try
        {
            Http.DefaultRequestHeaders.UserAgent.TryParseAdd("ResearchAgent/1.0");
            var json = await Http.GetStringAsync(url);
            var doc = System.Text.Json.JsonDocument.Parse(json);
            var root = doc.RootElement;

            if (root.TryGetProperty("extract", out var extract))
            {
                var title = root.TryGetProperty("title", out var t) ? t.GetString() : query;
                var pageUrl = root.TryGetProperty("content_urls", out var urls)
                    && urls.TryGetProperty("desktop", out var desktop)
                    && desktop.TryGetProperty("page", out var page)
                        ? page.GetString()
                        : "";
                return $"• {title}\n  {extract.GetString()}\n  Source: {pageUrl}";
            }
        }
        catch { /* fall through */ }

        return $"Search results for \"{query}\":\n"
             + "• No live results available. The agent should reason with its existing knowledge.\n"
             + "  (Set BING_SEARCH_API_KEY for real web search results.)";
    }
}

